if platforms is not None:
    if isinstance(platforms, str):
        raise TypeError(
            f"platforms must be an iterable of strings, not a single str"
        )
    normalized_platforms = frozenset(
        p.replace(".", "_").replace("-", "_").replace(" ", "_").lower()
        for p in platforms
    )
    if not any(
        t.platform == "any" or t.platform in normalized_platforms
        for t in tags
    ):
        raise InvalidWheelFilename(
            f"Wheel platform(s) {frozenset(t.platform for t in tags)!r} "
            f"not in given platforms {normalized_platforms!r}"
        )

